import bisect

def main():
    n = 1600
    sequence = [1, 2]
    elements_set = {1, 2}

    while len(sequence) < n:
        last = sequence[-1]
        T = last + 1
        while True:
            threshold = T / 2
            high = bisect.bisect_right(sequence, threshold)
            count = 0
            # Check pairs from the end down to high index
            for i in range(len(sequence)-1, high-1, -1):
                S = sequence[i]
                a = T - S
                if a in elements_set:
                    count += 1
                    if count >= 2:
                        break  # Found two pairs, invalid
            if count == 1:
                sequence.append(T)
                elements_set.add(T)
                break
            else:
                T += 1

    for idx in range(n):
        if idx == 0:
            diff = 0
        else:
            diff = sequence[idx] - sequence[idx-1]
        print(f"{idx+1} {sequence[idx]} {diff}")

if __name__ == "__main__":
    main()
