// Animation parameters
const totalDuration = 2000;     // Total animation time (ms)
const pulseStart = 800;         // When pulse begins (ms)
const pulseDuration = 400;      // Duration of pulse (ms)
const maxScale = 4;             // Scale to fill 32px height (8px * 4 = 32px)

function animate(currentTime) {
  if (!startTime) startTime = currentTime;
  const elapsed = (currentTime - startTime) % totalDuration;

  // Calculate horizontal position (0% to 100%)
  const progress = elapsed / totalDuration;
  const xPercent = progress * 100;

  // Calculate vertical scale (triangle waveform)
  let scale = 1;
  if (elapsed >= pulseStart && elapsed <= pulseStart + pulseDuration) {
    const pulseElapsed = elapsed - pulseStart;
    const halfDuration = pulseDuration / 2;

    // Linear interpolation for triangle wave
    if (pulseElapsed <= halfDuration) {
      scale = 1 + (pulseElapsed / halfDuration) * (maxScale - 1);
    } else {
      scale = maxScale - ((pulseElapsed - halfDuration) / halfDuration) * (maxScale - 1);
    }
  }

  // Apply combined transforms
  dot.style.transform = `translateX(${xPercent}%) translateY(-50%) scaleY(${scale})`;

  requestAnimationFrame(animate);
}

requestAnimationFrame(animate);
