### 🧾 Code Implementation (React Native)

Here is the updated code for `DrawingCanvas.js` to implement batch transition logic:

```javascript
// components/DrawingCanvas.js
import React, { useState, useEffect, useRef } from 'react';
import {
  View,
  Dimensions,
  StyleSheet,
  PanResponder,
  Text,
  Alert,
} from 'react-native';
import Svg, { Circle, Path, Text as SvgText } from 'react-native-svg';
import { fetchPoints } from '../services/api';

const { width, height } = Dimensions.get('window');

const DrawingCanvas = () => {
  const [points, setPoints] = useState([]);
  const [currentBatch, setCurrentBatch] = useState(0);
  const [lines, setLines] = useState([]);
  const [currentPath, setCurrentPath] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const batchSize = 10;
  const padding = 40;

  // Coordinate scaling
  const scalePoint = (point) => {
    return {
      x: (point.x / 2160) * (width - 2 * padding) + padding,
      y: (point.y / 2160) * (height - 2 * padding) + padding,
    };
  };

  // Fetch points from API
  useEffect(() => {
    const loadPoints = async () => {
      try {
        const data = await fetchPoints();
        setPoints(data);
        setLoading(false);
      } catch (err) {
        setError('Failed to load points');
        Alert.alert(
          'Error',
          'Failed to load points. Please check your connection.',
          [{ text: 'OK' }]
        );
        setLoading(false);
      }
    };

    loadPoints();
  }, []);

  // Find closest point to touch
  const findClosestPoint = (x, y) => {
    const startIdx = currentBatch * batchSize;
    const endIdx = Math.min(startIdx + batchSize, points.length);
    let closest = null;
    let minDist = 2500; // 50px radius threshold

    for (let i = startIdx; i < endIdx; i++) {
      const scaled = scalePoint(points[i]);
      const dx = scaled.x - x;
      const dy = scaled.y - y;
      const dist = dx * dx + dy * dy;

      if (dist < minDist) {
        minDist = dist;
        closest = scaled;
      }
    }

    return minDist < 2500 ? closest : null;
  };

  // Touch handling
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt, gestureState) => {
        const touchX = gestureState.x;
        const touchY = gestureState.y;
        const closest = findClosestPoint(touchX, touchY);

        if (closest) {
          setCurrentPath([closest.x, closest.y]);
        }
      },
      onPanResponderMove: (evt, gestureState) => {
        if (currentPath.length === 0) return;

        setCurrentPath(prev => [...prev, gestureState.x, gestureState.y]);
      },
      onPanResponderRelease: () => {
        if (currentPath.length > 0) {
          setLines(prev => [...prev, { points: [...currentPath] }]);
          setCurrentPath([]);
        }

        const nextBatchStart = (currentBatch + 1) * batchSize;
        if (nextBatchStart < points.length) {
          setCurrentBatch(prev => prev + 1);
        }
      },
    })
  ).current;

  if (loading) {
    return <Text style={styles.loading}>Loading points...</Text>;
  }

  if (error) {
    return <Text style={styles.error}>{error}</Text>;
  }

  const startIdx = currentBatch * batchSize;
  const currentPoints = points
    .slice(startIdx, startIdx + batchSize)
    .map(p => scalePoint(p));

  return (
    <View style={styles.container} {...panResponder.props}>
      <Svg style={styles.svg}>
        {/* Existing lines */}
        {lines.map((line, index) => (
          <Path
            key={`line-${index}`}
            d={`M ${line.points.join(' ')}`}
            stroke="blue"
            strokeWidth="2"
            fill="none"
          />
        ))}

        {/* Current path */}
        {currentPath.length > 0 && (
          <Path
            d={`M ${currentPath.join(' ')}`}
            stroke="blue"
            strokeWidth="2"
            fill="none"
          />
        )}

        {/* Current batch points */}
        {currentPoints.map((point, index) => (
          <Circle
            key={`point-${startIdx + index}`}
            cx={point.x}
            cy={point.y}
            r={10}
            fill="red"
          />
        ))}

        {/* Point labels */}
        {currentPoints.map((point, index) => (
          <SvgText
            key={`label-${startIdx + index}`}
            x={point.x + 5}
            y={point.y + 5}
            fontSize="14"
            fill="black"
          >
            {startIdx + index + 1}
          </SvgText>
        ))}
      </Svg>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: 'white',
  },
  svg: {
    flex: 1,
  },
  loading: {
    flex: 1,
    textAlign: 'center',
    marginTop: 50,
  },
  error: {
    color: 'red',
    textAlign: 'center',
    margin: 20,
  },
});

export default DrawingCanvas;
```

### 📌 Summary

- **Batch Transitions**: The `currentBatch` index is incremented on touch release, triggering a redraw of only the next set of points.
- **User Line Retention**: All completed user-drawn lines are stored in `lines` and redrawn with each batch.
- **Final State**: When all points are processed, `currentBatch` exceeds the number of available points, so no points are drawn, leaving only the user-drawn lines.

This implementation ensures a clean and intuitive user experience where the final set of points is automatically erased, leaving only the user-drawn curve visible.

