const worker = new Worker('csvImportQueue', async job => {
    const { csvPath, dbConfig, adminEmail } = job.data;

    // Fork a child process to handle the CSV import
    const child = fork(join(__dirname, 'csvProcessor.js'));

    // Send data to child process
    child.send({ csvPath, dbConfig, adminEmail });

    // Handle response from child process
    return new Promise((resolve, reject) => {
        child.on('message', (response) => {
            if (response.error) {
                reject(new Error(response.error));
            } else {
                resolve(response.result);
            }
        });

        child.on('error', (error) => {
            reject(error);
        });

        child.on('exit', (code) => {
            if (code !== 0) {
                reject(new Error(`Child process exited with code ${code}`));
            }
        });
    });
});

