const processCSV = async (csvPath, dbConfig, admin) => {
    const client = new Client(JSON.parse(dbConfig));
    const batchSize = 500;
    let batch = [];

    try {
        await client.connect();

        const stream = fs.createReadStream(csvPath);

        papaparse.parse(stream, {
            header: true,
            worker: true,
            step: async (results, parser) => {
                batch.push(results.data[0]);

                if (batch.length >= batchSize) {
                    await insertBatch(client, batch);
                    batch = [];
                }
            },
            complete: async () => {
                if (batch.length > 0) {
                    await insertBatch(client, batch);
                }

                const result = await sendNotification(true, admin);
                process.send({ result });
                await client.end();
            },
            error: async (err) => {
                const result = await sendNotification(false, admin, err.message);
                process.send({ error: result.error });
                await client.end();
            }
        });

    } catch (err) {
        const result = await sendNotification(false, admin, err.message);
        process.send({ error: result.error });
        await client.end();
    }
};
